def parse_record(text, delimiter=","):
    """Split one delimited record into its fields. See TASK.md."""
    # Validate delimiter
    if not isinstance(delimiter, str) or len(delimiter) != 1:
        raise ValueError("delimiter must be exactly one character")
    if delimiter in ('"', '\n', '\r'):
        raise ValueError("delimiter cannot be quote, newline, or carriage return")

    fields = []
    i = 0

    while True:
        # Read one field
        if i >= len(text):
            # Empty string or we just consumed a delimiter at the end
            fields.append("")
            break

        if text[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < len(text):
                if text[i] == '"':
                    # Check if it's an escaped quote
                    if i + 1 < len(text) and text[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        break
                else:
                    field += text[i]
                    i += 1
            else:
                # Reached end without closing quote
                raise ValueError("Unclosed quoted field")

            fields.append(field)

            # After closing quote, must be delimiter or end
            if i < len(text) and text[i] != delimiter:
                raise ValueError("Invalid character after quoted field")
        else:
            # Unquoted field
            field = ""
            while i < len(text) and text[i] != delimiter:
                if text[i] == '"':
                    raise ValueError("Quote in unquoted field")
                if text[i] in ('\n', '\r'):
                    raise ValueError("Newline/carriage return outside quoted field")
                field += text[i]
                i += 1

            fields.append(field)

        # Check what comes after the field
        if i >= len(text):
            # End of text
            break
        else:
            # Must be delimiter
            i += 1
            # Check if this is the end
            if i >= len(text):
                # We just consumed the last delimiter, so there's an empty field after
                fields.append("")
                break

    return fields


def format_record(fields, delimiter=","):
    """Write fields as one delimited record. See TASK.md."""
    # Validate delimiter
    if not isinstance(delimiter, str) or len(delimiter) != 1:
        raise ValueError("delimiter must be exactly one character")
    if delimiter in ('"', '\n', '\r'):
        raise ValueError("delimiter cannot be quote, newline, or carriage return")

    # Validate fields
    try:
        fields_list = list(fields)
    except TypeError:
        raise ValueError("fields must be iterable")

    if not fields_list:
        raise ValueError("fields must have at least one field")

    for field in fields_list:
        if not isinstance(field, str):
            raise ValueError("every field must be a str")

    result = []
    for field in fields_list:
        # Check if field needs quoting
        needs_quoting = (
            delimiter in field or
            '"' in field or
            '\n' in field or
            '\r' in field or
            (field and (field[0] == ' ' or field[-1] == ' '))
        )

        if needs_quoting:
            # Escape quotes by doubling
            escaped = field.replace('"', '""')
            result.append(f'"{escaped}"')
        else:
            result.append(field)

    return delimiter.join(result)
